import {
  createListbox,
  type Listbox as ListboxController,
  type ListboxItemInput,
  type ListboxSelectionMode,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, For, untrack } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** An option: a string that is both its label and its value, or an object with a label and its own details. */
export type ListboxItem = ListboxItemInput;

export interface ListboxProps {
  /** The options, in order. A getter (`() => items()`) lets the list arrive later or change. */
  readonly items: ReadonlyArray<ListboxItem> | (() => ReadonlyArray<ListboxItem>);
  /** `single` (the default) is one chosen row; `multiple` adds the check marks; `none` moves a cursor only. */
  readonly selectionMode?: ListboxSelectionMode | undefined;
  /** Controlled selection: the host owns it and `value` is the only thing that changes it. */
  readonly value?: ReadonlyArray<number> | undefined;
  /** Uncontrolled starting selection. */
  readonly defaultValue?: ReadonlyArray<number> | undefined;
  /** A request to change the selection; controlled, the host may ignore it. */
  readonly onValueChange?: ((value: ReadonlyArray<number>) => void) | undefined;
  /** Controlled active option (the type-ahead focus move's value). */
  readonly activeValue?: number | undefined;
  /** A request to move the active option. */
  readonly onActiveChange?: ((index: number) => void) | undefined;
  /** Single-select only: moving the active option moves the selection with it. */
  readonly followsFocus?: boolean | undefined;
  /** Whether a pointer over a row makes it active. */
  readonly focusOnHover?: boolean | undefined;
  /** Option indices that cannot be selected or reached by navigation. */
  readonly disabled?: ReadonlyArray<number> | undefined;
  /** The list's accessible name. */
  readonly label?: string | undefined;
  /** Base for the generated option ids. */
  readonly id?: string | undefined;
  /**
   * `"polyfill"` skips the feature detect and drives
   * `@microsoft/focusgroup-polyfill`'s low-level group even where the engine has
   * `focusgroup` (a test, or a host that knows it needs the polyfill). `"auto"`
   * by default.
   */
  readonly provider?: "auto" | "polyfill" | undefined;
  readonly class?: string | undefined;
  /** The primitive, once: a page that drives the list from elsewhere. */
  readonly onReady?: ((listbox: ListboxController) => void) | undefined;
}

// The list is its own frame: the surface, the border and the radius are the kit's, and the dark mode moves the tokens
// underneath. It is the option set, so each row announces its place and size (`aria-posinset` / `aria-setsize`) inside it.
const listClass = css.cn(
  css.display("grid"),
  css.margin("0"),
  css.padding(t.space._1),
  css.listStyle("none"),
  css.maxHeight("20rem"),
  css.overflowY("auto"),
  css.boxSizing("border-box"),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.lg),
  css.fontSize(t.font.size),
  css.userSelect("none"),
);

// A row paints the two states the primitive announces and nothing else: the active row is the primitive's
// `aria-activedescendant` (the skin mirrors it as `data-highlighted`), the chosen one is `aria-selected`, and a disabled
// one is `aria-disabled`. The row is the group the check mark reads, so the skin keeps no copy of the selection either.
const rowClass = css.cn(
  css.group(),
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.minHeight(t.space._8),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.outline("none"),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.attr("data-highlighted", "true")(css.bg(t.color.buttonBackground)),
  css.attr("aria-selected", "true")(
    css.bg(t.color.buttonBackgroundPressed),
    css.fontWeight("500"),
    css.hover(css.bg(t.color.buttonBackgroundPressed)),
  ),
  css.attr("aria-disabled", "true")(
    css.color(t.color.textDisabled),
    css.cursor("not-allowed"),
    css.hover(css.bg("transparent")),
  ),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out"),
  ),
);

const checkClass = css.cn(
  css.width("1em"),
  css.flexShrink("0"),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.visibility("hidden"),
  css.within(css.attr("aria-selected", "true"))(css.visibility("visible")),
);

const labelClass = css.cn(
  css.overflow("hidden"),
  css.whiteSpace("nowrap"),
  css.textOverflow("ellipsis"),
);

/**
 * A plain listbox, styled: `createListbox` owns the options, the active option, the selection, the ARIA and the keys, and the
 * platform's `focusgroup` contract (`listbox block nowrap`) owns the roving tab stop, the arrows and Home / End. The skin is
 * the frame, the highlight painted from `data-highlighted` (the row `aria-activedescendant` names), the selected fill, the
 * check mark in a multiple list, the disabled grey, the focus ring and the DOM focus that follows the primitive's active
 * option — a type-ahead move and a click change the active option without a key, so the host moves the real focus there.
 *
 * DOM focus lives on the rows, the same rows the model names: a move the platform makes is read back through `onFocus`, so
 * one state follows the DOM and no effect has to guess which row is the tab stop.
 */
export const Listbox = (props: ListboxProps): JSX.Element => {
  const listbox = createListbox({
    get items() {
      return props.items;
    },
    selectionMode: props.selectionMode,
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get onValueChange() {
      return props.onValueChange;
    },
    get activeValue() {
      return props.activeValue;
    },
    get onActiveChange() {
      return props.onActiveChange;
    },
    followsFocus: props.followsFocus,
    focusOnHover: props.focusOnHover,
    disabled: props.disabled,
    get label() {
      return props.label;
    },
    id: props.id,
    provider: props.provider,
  });
  // a structural prop, read once: it is the primitive for a fixture, not a signal
  untrack(() => props.onReady)?.(listbox);

  const multiple = (): boolean => listbox.selectionMode === "multiple";
  const highlighted = (index: number): boolean => listbox.focused() && listbox.active() === index;

  let list: HTMLUListElement | undefined;
  const rows = (): ReadonlyArray<HTMLElement> => [
    ...(list?.querySelectorAll<HTMLElement>('[role="option"]') ?? []),
  ];
  // The platform owns the tab stop; what it cannot know is a programmatic move
  // (type-ahead, a click, a controlled `activeValue`), so the host focuses the
  // active row while focus is inside, and the platform's own move is a no-op here.
  createEffect(
    () => `${listbox.focused()}|${listbox.active()}`,
    () => {
      if (!listbox.focused()) {
        return;
      }
      const row = rows()[listbox.active()];
      if (row !== undefined && row !== document.activeElement) {
        row.focus();
      }
    },
  );

  return (
    <ul
      {...listbox.listboxProps}
      data-part="listbox"
      class={css.cn(listClass, props.class)}
      ref={(node: HTMLUListElement) => {
        list = node;
        listbox.listboxProps.ref(node);
      }}
    >
      <For each={listbox.items}>
        {(item, index) => (
          <li
            {...listbox.optionProps(index())}
            data-part="listbox-option"
            data-highlighted={highlighted(index()) ? "true" : "false"}
            class={rowClass}
          >
            {multiple() ? (
              <span data-part="listbox-check" aria-hidden="true" class={checkClass}>
                ✓
              </span>
            ) : null}
            <span data-part="listbox-label" class={labelClass}>
              {item.label}
            </span>
          </li>
        )}
      </For>
    </ul>
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import type { Json } from "@cssints/apg-specs/scenario";
import type { ListboxMountConfig } from "@cssints/apg-specs/apg/listbox-shared";
import type { Listbox as ListboxController } from "@cssints/headless";
import type { Mounted } from "./listbox-driver.ts";
import { Listbox } from "./listbox.tsx";
import { createSignal } from "solid-js";
import { render } from "@solidjs/web";

const isJsonObject = (value: Json): value is Readonly<Record<string, Json>> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const asRecord = (value: Json | undefined): Readonly<Record<string, Json>> => {
  if (value === undefined || !isJsonObject(value)) {
    throw new Error(`expected an object, got ${JSON.stringify(value)}`);
  }
  return value;
};

/**
 * The walk's `key` steps are programmatic (`prop` steps), so they become a real
 * keydown on the focused row: the platform moves focus along the block axis, the
 * primitive prevents the keys it owns. The walk alphabet spells arrows short.
 */
const dispatchKey = (target: HTMLElement, value: Json | undefined): void => {
  const record = asRecord(value);
  const key = record["key"];
  if (typeof key !== "string") {
    throw new Error(`key needs a string key, got ${JSON.stringify(value)}`);
  }
  const named = ["Left", "Right", "Up", "Down"].includes(key) ? `Arrow${key}` : key;
  target.dispatchEvent(
    new KeyboardEvent("keydown", {
      key: named === "Space" ? " " : named,
      shiftKey: record["shift"] === true,
      ctrlKey: record["ctrl"] === true,
      metaKey: record["meta"] === true,
      altKey: record["alt"] === true,
      bubbles: true,
      cancelable: true,
    }),
  );
};

/**
 * Mounts the styled listbox for the scenario walk: the same props the primitive's fixture passes, the primitive it built
 * through `onReady`, and the `Mounted` the DOM driver needs. The skin's rows are `listbox-option` parts; the test translates
 * the scenario's `option` targets to them.
 *
 * The walk drives the polyfill provider: its `key` steps are untrusted keydowns, which a native engine ignores.
 *
 * Controlled, the fixture is the host: it keeps the selection (or, in `selectionMode: 'none'`, the active option) in a
 * signal, passes it as `value` / `activeValue`, and either writes every request back (`accepts`) or ignores the callback.
 */
export const mountListbox = (config: ListboxMountConfig): Mounted => {
  const root = document.createElement("div");
  document.body.append(root);
  const events = new Map<string, Json[]>();
  const labels = config.items;
  // the type-ahead model's value is the active option, not the selection
  const activeMode = config.selectionMode === "none";
  const [host, setHost] = createSignal<ReadonlyArray<number>>(config.defaultSelected);
  const [activeHost, setActiveHost] = createSignal(config.defaultActive ?? 0);
  const writeHost = (next: ReadonlyArray<number>): void => {
    if (config.controlled && !activeMode) {
      setHost([...next]);
    }
  };
  const writeActive = (index: number): void => {
    if (config.controlled && activeMode) {
      setActiveHost(index);
    }
  };
  const append = (name: string, payload: Json): void => {
    events.set(name, [...(events.get(name) ?? []), payload]);
  };
  let api: ListboxController | undefined;

  const optionElements = (): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>('[data-part="listbox-option"]'),
  ];

  const dispose = render(
    () => (
      <Listbox
        items={labels}
        selectionMode={config.selectionMode}
        followsFocus={config.followsFocus}
        defaultValue={config.defaultSelected}
        value={config.controlled && !activeMode ? host() : undefined}
        activeValue={config.controlled && activeMode ? activeHost() : undefined}
        disabled={config.disabled}
        focusOnHover={config.focusOnHover}
        label={config.ariaLabel}
        provider="polyfill"
        onReady={(listbox) => {
          api = listbox;
        }}
        onValueChange={(selected) => {
          // The ported scenarios encode `onSelectionChange` as the current
          // selection keys (not an invocation history), so replace each time;
          // the differential walk reads the append-only `onValueChange` history.
          const payload = selected.map((index) => labels[index] ?? "");
          events.set("onSelectionChange", payload);
          append("onValueChange", payload);
          if (config.accepts) {
            writeHost(selected);
          }
        }}
        onActiveChange={(index) => {
          if (!activeMode) {
            return;
          }
          append("onActiveChange", String(index));
          if (config.accepts) {
            writeActive(index);
          }
        }}
      />
    ),
    root,
  );

  if (config.autoFocus !== undefined && config.autoFocus !== false) {
    const index = api?.focus() ?? 0;
    optionElements()[index]?.focus();
  }

  return {
    root,
    events,
    setProp: (name, value) => {
      switch (name) {
        case "focus":
          api?.focus();
          break;
        case "blur":
          api?.blur();
          break;
        case "key": {
          // a real keydown on the focused row: the platform moves the active
          // option, the primitive's own listener runs its keys; a key step with
          // focus outside the list is the model's no-op
          const index = api?.focused() === true ? (api?.active() ?? -1) : -1;
          const target = index >= 0 ? optionElements()[index] : undefined;
          if (target !== undefined) {
            dispatchKey(target, value);
          }
          break;
        }
        case "type":
          api?.type(String(value));
          break;
        case "typeaheadTimeoutElapsed":
          api?.clearTypeahead();
          break;
        case "followsFocus":
        case "set_follows_focus":
          api?.setFollowsFocus(value === true);
          break;
        case "setValue":
        case "value":
        case "selected":
          if (Array.isArray(value)) {
            writeHost(value.map(Number));
          } else if (typeof value === "number" && Number.isInteger(value)) {
            writeActive(value);
          } else {
            throw new Error(`setValue needs indices, got ${JSON.stringify(value)}`);
          }
          break;
        case "hostToggle":
          if (activeMode) {
            writeActive((activeHost() + 1) % labels.length);
          } else {
            writeHost(host().includes(0) ? host().filter((index) => index !== 0) : [...host(), 0]);
          }
          break;
        case "selectionModel":
        case "set_selection_model":
          break;
        default:
          throw new Error(`fixture has no prop ${name}`);
      }
    },
    focus: () => (api?.focused() === true ? `option:${api.active()}` : null),
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type ActionStep, type Driver, type Json, Unsupported } from "@cssints/apg-specs/scenario";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";

/**
 * The generic DOM side of the scenario bridge. A pattern's fixture renders its
 * parts with `data-part="<name>"` and returns a `Mounted`; this turns scenario
 * steps into real pointer/keyboard input and DOM reads into observations.
 */
export interface Mounted {
  readonly root: HTMLElement;
  /** Apply a scenario `prop` step (programmatic input) to the mounted widget. */
  readonly setProp: (name: string, value: Json | undefined) => void;
  /** Callback payloads, recorded under their canonical name. */
  readonly events: ReadonlyMap<string, ReadonlyArray<Json>>;
  readonly value?: () => Json;
  /**
   * The part the primitive itself considers focused (`trigger`, `tab:1`), or
   * `null`. Preferred over `document.activeElement` so the walk does not race the
   * fixtures' deferred DOM focus (bean 209r).
   */
  readonly focus?: () => string | null;
  readonly dispose: () => void;
}

export interface DomDriverOptions {
  /** Parts that can be hidden: the ones `expect.visible` lists. */
  readonly hideableParts: ReadonlyArray<string>;
  readonly eventName?: (name: string) => string;
}

const BOOLEAN_ATTRS = new Set(["hidden", "disabled"]);
const REFERENCE_ATTRS = new Set([
  "aria-controls",
  "aria-labelledby",
  "aria-owns",
  "aria-activedescendant",
]);
const NAMED_KEYS = new Set(["Enter", "Tab", "Escape", "Backspace", "Delete", "Home", "End"]);

// Solid renders on its own schedule, but `flush()` applies the queued signal work
// synchronously; the fixtures then move DOM focus in a `setTimeout(0)` macrotask
// (kept for user-event's Enter semantics). Waiting one macrotask lets both land
// before the walk reads, without a frame — a frame also lets the browser's focus
// fixup run and perturb the observation (bean 209r). The walk reads focus from
// the fixture's primitive state when it offers one (`Mounted.focus`).
const settle = (): Promise<void> => {
  flush();
  return new Promise((resolve) => {
    setTimeout(resolve, 0);
  });
};

const keyboardSyntax = (key: string): string => {
  if (key === "Space" || key === " ") {
    return " ";
  }
  return NAMED_KEYS.has(key) || key.startsWith("Arrow") || key.startsWith("Page")
    ? `{${key}}`
    : key;
};

// A held key is always written by name: `{Space>}` keeps it down, `{/Space}`
// releases it wherever focus is at that moment (a blur between the two halves
// is exactly what a walk needs to see).
const keyName = (key: string) => (key === " " || key === "Space" ? "Space" : key);

/** `KeyboardEvent.key` uses a space character, not the `Space` alias. */
const eventKey = (key: string) => (key === "Space" ? " " : key);

const CLICKABLE_INPUT_TYPES = new Set([
  "button",
  "color",
  "file",
  "image",
  "reset",
  "submit",
  "checkbox",
  "radio",
]);

/**
 * A half press is dispatched directly (not through user-event's held-key state,
 * which auto-releases on a repeated down and leaks across walk drivers). The
 * two native activations user-event would otherwise add are emulated: Space
 * clicks a button-like element on keyup, Enter on keydown.
 */
const halfPress = (target: EventTarget | null, type: "keydown" | "keyup", key: string) => {
  if (!(target instanceof HTMLElement)) {
    return;
  }
  const keyValue = eventKey(key);
  const notPrevented = target.dispatchEvent(
    new KeyboardEvent(type, {
      key: keyValue,
      code: keyName(key),
      bubbles: true,
      cancelable: true,
    }),
  );
  const clickable =
    target.tagName === "BUTTON" ||
    (target instanceof HTMLInputElement && CLICKABLE_INPUT_TYPES.has(target.type));
  if (
    notPrevented &&
    clickable &&
    ((type === "keyup" && keyValue === " ") || (type === "keydown" && keyValue === "Enter"))
  ) {
    target.click();
  }
};

export const domDriver = (mounted: Mounted, options: DomDriverOptions): Driver => {
  const { root } = mounted;
  const canonical = options.eventName ?? ((name: string) => name);

  const partsOf = (name: string): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>(`[data-part="${name}"]`),
  ];

  const targetOf = (element: HTMLElement): string => {
    const name = element.dataset["part"] ?? "";
    return `${name}:${partsOf(name).indexOf(element)}`;
  };

  const elementOf = (target: string): HTMLElement => {
    const [name = "", index = "0"] = target.split(":");
    const element = partsOf(name)[Number(index)];
    if (element === undefined) {
      throw new Unsupported(`part ${target}`);
    }
    return element;
  };

  const click = async (element: HTMLElement): Promise<void> => {
    // a disabled button is not actionable; force lets the browser drop the click itself
    await userEvent.click(element, { force: true });
  };

  // Half presses this driver dispatched a keydown for, so a stray `phase: "up"`
  // stays inert (the spec's key_up only fires on an armed press).
  const halfHeld = new Set<string>();

  return {
    perform: async (step: ActionStep) => {
      switch (step.event) {
        case "focus":
          elementOf(step.target ?? "").focus();
          break;
        case "blur":
          halfHeld.clear();
          elementOf(step.target ?? "").blur();
          break;
        case "click":
          await click(elementOf(step.target ?? ""));
          break;
        case "pointerdown":
          elementOf(step.target ?? "").focus();
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointerdown", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "pointerup": {
          const element = elementOf(step.target ?? "");
          element.dispatchEvent(
            new PointerEvent("pointerup", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          // a released pointer button is a click, as the browser would deliver it
          element.click();
          break;
        }
        case "pointercancel":
          elementOf(step.target ?? "").dispatchEvent(
            new PointerEvent("pointercancel", {
              bubbles: true,
              cancelable: true,
              pointerType: step.pointerType ?? "mouse",
            }),
          );
          break;
        case "hover":
          await userEvent.hover(elementOf(step.target ?? ""));
          break;
        case "unhover":
          await userEvent.unhover(elementOf(step.target ?? ""));
          break;
        case "key": {
          if (step.phase === "down") {
            const element = elementOf(step.target ?? "");
            if (document.activeElement !== element) {
              element.focus();
            }
            // a disabled/read-only control never arms (the spec's spaceArms
            // guard), so a later `up` must not activate it either
            const blocked =
              element.getAttribute("aria-disabled") === "true" ||
              element.getAttribute("aria-readonly") === "true" ||
              (element instanceof HTMLButtonElement && element.disabled);
            if (!blocked) {
              halfHeld.add(keyName(step.key ?? ""));
            }
            halfPress(element, "keydown", step.key ?? "");
            break;
          }
          if (step.phase === "up") {
            if (!halfHeld.delete(keyName(step.key ?? ""))) {
              break;
            }
            // release wherever focus went: deliberately do NOT re-focus the
            // target, or a keydown -> blur -> keyup walk would be defeated
            const active = document.activeElement;
            halfPress(
              active instanceof HTMLElement ? active : document.body,
              "keyup",
              step.key ?? "",
            );
            break;
          }
          const element = elementOf(step.target ?? "");
          if (document.activeElement !== element) {
            element.focus();
          }
          // a whole press releases the key, so a later `phase: "up"` is inert
          halfHeld.delete(keyName(step.key ?? ""));
          await userEvent.keyboard(keyboardSyntax(step.key ?? ""));
          break;
        }
        case "prop":
          if (step.set !== undefined) {
            for (const [name, value] of Object.entries(step.set)) {
              mounted.setProp(name, value);
              if ((name === "disabled" || name === "isDisabled") && value === true) {
                // the spec drops a pending press when the control disables
                halfHeld.clear();
              }
            }
          } else {
            mounted.setProp(step.prop ?? "", step.value);
            if ((step.prop === "disabled" || step.prop === "isDisabled") && step.value === true) {
              halfHeld.clear();
            }
          }
          break;
        default:
          throw new Unsupported(`event ${step.event}`);
      }
      await settle();
    },
    observer: {
      focus: () => {
        // Prefer the primitive's own focus: the fixtures sync DOM focus in a
        // deferred macrotask (kept for user-event's Enter semantics), so reading
        // `document.activeElement` here races that (bean 209r).
        if (mounted.focus !== undefined) {
          return mounted.focus();
        }
        const active = document.activeElement;
        const part =
          active instanceof HTMLElement ? active.closest<HTMLElement>("[data-part]") : null;
        return part !== null && root.contains(part) ? targetOf(part) : null;
      },
      attr: (target, name) => {
        if (name.startsWith("data-")) {
          throw new Unsupported(`styling hook ${name}`);
        }
        const value = elementOf(target).getAttribute(name);
        if (value === null) {
          return null;
        }
        if (value === "" && BOOLEAN_ATTRS.has(name)) {
          return "true";
        }
        if (REFERENCE_ATTRS.has(name)) {
          const referenced = root.querySelector<HTMLElement>(`[id="${value}"]`);
          return referenced?.dataset["part"] === undefined ? value : targetOf(referenced);
        }
        return value;
      },
      visible: () =>
        options.hideableParts.flatMap((name) =>
          partsOf(name)
            .filter((element) => element.checkVisibility())
            .map(targetOf),
        ),
      events: (name) => mounted.events.get(canonical(name)) ?? [],
      ...(mounted.value === undefined ? {} : { value: mounted.value }),
    },
    dispose: mounted.dispose,
  };
};

